///<summary>
///How something ended: one vocabulary for every project.
///</summary>
public enum Outcome : byte
{
    cancelled = 5, //stopped on purpose
    failed = 2,    //failed
    none = 0,      //not about an outcome
    ok = 1,        //succeeded
    refused = 3,   //refused by the other side or by a rule
    timeout = 4,   //did not finish in time

}
///<summary>
///Компоненты тестеров и Monitoring: что доставляет Updater (`Updater.Component`), что раскладывают стартеры
///(`TesterFormatter.Install`) и что видно на странице Deployment.
///</summary>
public enum Part : byte
{
    collections_c = 12, //коллекции C ( PrimitiveCollectionsC ): у тестера - lib/collections хоста C и Python
                        ///<summary>
                        ///Значения - по порядку объявления, в провод идёт само значение. Новый компонент встаёт последним,
                        ///перед `reserved`: прежние не сдвигаются. Убрать компонент или вставить его в середину - значит
                        ///сдвинуть следующие за ним: стартеры вшиты в образы, образы тогда заменяются вместе с Server.
                        ///</summary>
    collections_java = 0,
    lib_c = 11,
    lib_cpp = 10,
    lib_cs = 2,
    lib_go = 9,
    lib_java = 1,
    lib_py = 13, //прослойка Python над выдачей C
    lib_rs = 8,
    lib_ts = 3,
    monitoring = 7, //программа Monitoring (хост Monitoring), её ставит стартер MonitoringFormatter
    node_modules = 4,
    nuget = 5,
    ///<summary>
    ///Не компонент - ширина поля: последнее значение держит поле в 4 битах, до 16 значений.
    ///</summary>
    reserved = 14,
    tester = 6, //бинарник протокола хоста Tester

}

